/**
 * Pure URL helpers for embedded media (03 · Media, 01 · Headers). No React, no DOM.
 *
 * - Video links (YouTube, Vimeo, Loom, Google Drive) become the host's player URL, built only
 *   after a visitor presses play. YouTube always uses its privacy-enhanced youtube-nocookie.com.
 * - Only `https:` URLs on the allowed frame hosts are ever turned into iframe addresses.
 */
import { isHttpsUrl, isRelativePath, isSafeLink } from "./schemas.ts";

export type VideoHost = "youtube" | "vimeo" | "loom" | "drive";

/** The origins the public CSP allows in `frame-src` for videos and embeds (01 · Headers). */
export const FRAME_HOSTS = [
  "https://www.youtube-nocookie.com",
  "https://player.vimeo.com",
  "https://www.loom.com",
  "https://drive.google.com",
  "https://www.figma.com",
] as const;

const HOST_LABELS: Record<VideoHost, string> = {
  youtube: "YouTube",
  vimeo: "Vimeo",
  loom: "Loom",
  drive: "Google Drive",
};

/** The host's display name, as Studio and the poster say it: "YouTube", "Google Drive"… */
export function videoHostLabel(host: VideoHost): string {
  return HOST_LABELS[host];
}

function parse(value: string): URL | null {
  if (!isHttpsUrl(value)) return null;
  try {
    return new URL(value);
  } catch {
    /* c8 ignore next */
    return null;
  }
}

/** The bare host name, without a leading `www.` or `m.`. */
function bareHost(url: URL): string {
  return url.hostname.toLowerCase().replace(/^(www|m)\./, "");
}

const ID = /^[\w-]+$/;

/** Which supported video host a link points at, or null for anything else (06 · pm-check-link). */
export function videoHost(value: string): VideoHost | null {
  const url = parse(value);
  if (!url) return null;
  switch (bareHost(url)) {
    case "youtube.com":
    case "youtu.be":
    case "youtube-nocookie.com":
      return "youtube";
    case "vimeo.com":
    case "player.vimeo.com":
      return "vimeo";
    case "loom.com":
      return "loom";
    case "drive.google.com":
      return "drive";
    default:
      return null;
  }
}

/** A YouTube start time, `t=90`, `t=1m30s` or `start=90`, in whole seconds. */
function youtubeStart(url: URL): number | null {
  const raw = url.searchParams.get("t") ?? url.searchParams.get("start");
  if (!raw) return null;
  if (/^\d+s?$/.test(raw)) return parseInt(raw, 10);
  const m = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/.exec(raw);
  if (!m) return null;
  const [, h = "0", min = "0", s = "0"] = m;
  return parseInt(h, 10) * 3600 + parseInt(min, 10) * 60 + parseInt(s, 10);
}

function youtubeId(url: URL): string | null {
  const host = bareHost(url);
  const parts = url.pathname.split("/").filter(Boolean);
  if (host === "youtu.be") return parts[0] ?? null;
  if (url.pathname === "/watch") return url.searchParams.get("v");
  if (parts[0] === "embed" || parts[0] === "shorts" || parts[0] === "live") return parts[1] ?? null;
  return null;
}

/**
 * The player URL for a video link, or null if the link isn't a supported video.
 * The poster's play button is the click that starts it, so the player autoplays.
 */
export function toVideoEmbedUrl(value: string): string | null {
  const url = parse(value);
  const host = videoHost(value);
  if (!url || !host) return null;
  const parts = url.pathname.split("/").filter(Boolean);

  if (host === "youtube") {
    const id = youtubeId(url);
    if (!id || !ID.test(id)) return null;
    const start = youtubeStart(url);
    const query = new URLSearchParams({ autoplay: "1", rel: "0" });
    if (start) query.set("start", String(start));
    return `https://www.youtube-nocookie.com/embed/${id}?${query.toString()}`;
  }

  if (host === "vimeo") {
    // vimeo.com/123, vimeo.com/123/abcdef (unlisted), player.vimeo.com/video/123
    const [first, second] = bareHost(url) === "player.vimeo.com" ? parts.slice(1) : parts;
    if (!first || !/^\d+$/.test(first)) return null;
    const query = new URLSearchParams({ autoplay: "1", dnt: "1" });
    const hash = url.searchParams.get("h") ?? second;
    if (hash && /^[\da-f]+$/i.test(hash)) query.set("h", hash);
    return `https://player.vimeo.com/video/${first}?${query.toString()}`;
  }

  if (host === "loom") {
    // loom.com/share/<id> or loom.com/embed/<id>
    const id = parts[0] === "share" || parts[0] === "embed" ? parts[1] : undefined;
    if (!id || !ID.test(id)) return null;
    return `https://www.loom.com/embed/${id}?autoplay=1`;
  }

  // Google Drive: drive.google.com/file/d/<id>/view → /preview
  const id = parts[0] === "file" && parts[1] === "d" ? parts[2] : undefined;
  if (!id || !ID.test(id)) return null;
  return `https://drive.google.com/file/d/${id}/preview`;
}

/** A Figma file, design or prototype link as Figma's embed URL (posts' Embed block), or null. */
export function toFigmaEmbedUrl(value: string): string | null {
  const url = parse(value);
  if (!url || bareHost(url) !== "figma.com") return null;
  if (!/^\/(file|design|proto|board)\/[\w-]+/.test(url.pathname)) return null;
  return `https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent(url.toString())}`;
}

/** Any supported embed link (video or Figma) as its iframe address, or null. */
export function toEmbedUrl(value: string): string | null {
  return toVideoEmbedUrl(value) ?? toFigmaEmbedUrl(value);
}

/**
 * Whether an address may be used as an iframe `src`: `https:` only, and on one of the allowed
 * origins. Prototype origins are computed at build from published content, so callers pass them.
 */
export function isAllowedFrameUrl(value: string, extraOrigins: readonly string[] = []): boolean {
  const url = parse(value);
  if (!url) return false;
  return [...FRAME_HOSTS, ...extraOrigins].includes(url.origin);
}

/** Whether `value` is an `https:` address on a different origin from `siteOrigin`. */
export function isCrossOriginHttps(value: string, siteOrigin: string): boolean {
  const url = parse(value);
  return url !== null && url.origin !== siteOrigin;
}

/**
 * The address a prototype opens on: its deployed `https:` URL, plus an optional relative
 * `startPath` (a screen shortcut or a Prototype block's "Opens on"). The result always stays on
 * the prototype's own origin; anything else returns null.
 */
export function prototypeUrl(base: string, startPath?: string): string | null {
  const url = parse(base);
  if (!url) return null;
  if (!startPath) return url.toString();
  if (!isRelativePath(startPath)) return null;
  try {
    const dir = new URL(url.pathname.endsWith("/") ? url.pathname : `${url.pathname}/`, url.origin);
    const joined = new URL(startPath.replace(/^\/+/, ""), dir);
    return joined.origin === url.origin ? joined.toString() : null;
  } catch {
    /* c8 ignore next */
    return null;
  }
}

/**
 * The href to render for a link from content, or undefined when it breaks the 06 link rule
 * (https, mailto, a /path or a #section). Every component that renders a link from props uses
 * this, so a `javascript:` value can never reach the DOM even if it skipped schema validation.
 */
export function safeHref(href: string | undefined): string | undefined {
  return href !== undefined && isSafeLink(href) ? href : undefined;
}
